public class PostCompilePreventNullAnalysis {
	public void test() {
		Object o = "Hello World!";
		try {
			System.out.println(o);
		} finally {
			if (o != null) {
				if (lombok.Lombok.preventNullAnalysis(o) != null) {
					o.toString();
				}
			}
		}
	}

